SELECT 
FROM user_feedback f
WHERE f.user_id = #{userId}
ORDER BY f.created_at DESC
LIMIT #{offset}, #{limit}

SELECT ,
       u.username AS username,
       u.nickname AS nickname
FROM user_feedback f
LEFT JOIN users u ON u.id = f.user_id

    
        AND f.status = #{status}
    
    
        AND f.category = #{category}
    

ORDER BY f.created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM user_feedback f

    
        AND f.status = #{status}
    
    
        AND f.category = #{category}

SELECT 
FROM user_feedback f
WHERE f.id = #{id}
